('queue-open').onclick=()=>navigate('queue');for(const id of ['mini','mini-settings','mini-exit'])$(id).onclick=guarded(async()=>{const result=await call({op:'mini'});window.yuriWindowMode(result);});$('always-top').onclick=guarded(async()=>{const r=await call({op:'topmost'});toast(r.topmost?'Janela sempre por cima.':'Janela em modo normal.');});$('export').onclick=guarded(async()=>{const r=await call({op:'export',data:JSON.stringify(library)});if(r.saved)toast('Biblioteca exportada.');});$('import').onclick=guarded(importLibrary);$('sync-folder').onclick=guarded(async()=>{await call({op:'sync-folder'});await synchronize(true);});$('sync-now').onclick=guarded(()=>synchronize(true));$('sync-off').onclick=guarded(async()=>{await call({op:'sync-off'});$('sync-status').textContent='Sincronização desligada.';});$('downloads-folder').onclick=guarded(async()=>{await call({op:'downloads-folder'});});$('clear-cache').onclick=guarded(async()=>{const r=await call({op:'cache-clear'});$('cache-status').textContent=r.message;toast('Cache de capas limpo.');});window.command=action=>{if(action==='resume')return player.resume();if(action==='pause')return player.pause();if(action==='play')return player.toggle();if(action==='next')player.next();if(action==='previous')player.previous();if(action==='volume-up')setSetting('volume',Math.min(1,settings.volume+.05));if(action==='volume-down')setSetting('volume',Math.max(0,settings.volume-.05));};if('mediaSession'in navigator)for(const [event,action]of [['play',()=>player.resume()],['pause',()=>player.pause()],['previoustrack',()=>player.previous()],['nexttrack',()=>player.next()],['seekto',e=>{if(Number.isFinite(e.seekTime))player.seekTo(e.seekTime).catch(()=>{});}]])try{navigator.mediaSession.setActionHandler(event,action);}catch{}
const trackMenu=setupTrackMenu({enqueue:async s=>enqueueTrack(s),next:s=>{player.queue.splice(player.index+1,0,{...song(s),key:crypto.randomUUID()});if(player.index<0){player.index=0;playbackChanged('track');}session.save(true);render();toast('Vai tocar a seguir.');},radio:async s=>{if(isSpotify(s.id))throw Error('Rádio disponível para faixas YouTube Music.');const result=await call({op:'radio',id:s.id});const tracks=[song(s),...(result.songs||[]).filter(t=>t.id!==s.id).map(song)];await player.setQueue(tracks,0);},like:s=>like(s),liked:s=>!!library.likes[s.id]&&!library.likes[s.id].deleted,playlist:s=>addDialog(s),album:s=>openAlbum(s),artist:s=>openArtist(s),share:s=>share(s),remove:s=>{if(player.external)return player.removeQueue(s.key);const index=player.queue.findIndex(t=>t.key===s.key);if(index===player.index)throw Error('A faixa atual continua tocando.');if(index>=0){player.queue.splice(index,1);if(index<player.index)player.index--;session.save(true);render();}},error:e=>toast(e.message)});
async function boot(){try{const local=localStorage.getItem('noctune-library-preview-v1');if(local)library=validate(JSON.parse(local));}catch{toast('A biblioteca local não pôde ser lida. Tente importar um backup.');}try{const disk=await call({op:'state-load'});if(disk.data)library=merge(library,JSON.parse(disk.data));downloads=(await call({op:'downloads'})).songs.map(song);}catch(e){toast(e.message);}settings=library.settings.value;if(!localStorage.getItem('nocturne-meiro-migrated')){settings.musicSource='youtube';settings.retro=false;localStorage.setItem('nocturne-meiro-migrated','1');}applySettings();booted=true;renderSidebar();navigate(page);await session.restore();await synchronize(false);setInterval(()=>synchronize(false),30000);$('audio-info').textContent='Equalizador de 5 bandas, suavização opcional dos picos e visualizador limitado a 25 quadros por segundo. O modo discreto desativa o visualizador.';notificationsUI.start();updateUI.start();document.getElementById('splash')?.remove();window.yuriReady=true;loadFeed('home').catch(e=>toast(e.message));}
boot();

function renderCollections(){const items=page==='artist'?detail?.collections||[]:page==='search'?collections:[];$('collections').replaceChildren();for(const item of items){if(!/^[A-Za-z0-9_-]{2,160}$/.test(item.id))continue;const b=button('',item.type==='artist'?'Ver artista '+item.title:'Ver álbum '+item.title,()=>openCollection(item));b.className='collection';b.append(cover(item),node('b','',item.title),node('small','',item.year||item.artists||(item.type==='artist'?'Artista':'Álbum')));$('collections').append(b);}}
async function openCollection(item){const kind=['artist','playlist','podcast'].includes(item.type)?item.type:'album';navigate(kind==='playlist'?'playlist-remote':kind);detail=null;render();const ticket=browseGeneration;status(kind==='album'?'Carregando álbum…':'Carregando artista…');const loaded=await call({op:kind,id:item.id});const data={...loaded,title:loaded.title||item.title||'Álbum',thumbnail:loaded.thumbnail||item.thumbnail||(loaded.songs||[]).find(t=>t.thumbnail)?.thumbnail||''};if(kind==='album')data.songs=(data.songs||[]).map(t=>({...t,albumId:item.id,albumName:data.title,artists:t.artists||(data.artists||[]).map(a=>a.name).join(', '),artistId:t.artistId||data.artists?.[0]?.id||'',thumbnail:t.thumbnail||data.thumbnail}));if(ticket!==browseGeneration)return;detail={...data,songs:(data.songs||[]).map(song)};$('heading').textContent=data.title;$('intro').textContent=kind==='album'?[data.year,data.songs.length+' faixas'].filter(Boolean).join(' · '):'Músicas e lançamentos disponíveis';const hero=node('div','detail-hero'),img=cover({thumbnail:data.thumbnail}),text=node('div');text.append(node('small','label',({album:'ÁLBUM',artist:'ARTISTA',playlist:'PLAYLIST',podcast:'PODCAST'})[kind]),node('h2','',data.title));if(kind==='album')for(const artist of data.artists||[])text.append(button(artist.name,'Ver artista '+artist.name,()=>openCollection({type:'artist',id:artist.id}),'text-link'));if(kind==='artist'&&!isSpotify(item.id)){text.append(notificationsUI.followButton(item.id,data));text.append(button('Seguir no YouTube Music','Seguir artista na conta',async()=>{await call({op:'subscribe',id:item.id,enabled:true});toast('Artista seguido no YouTube Music.');}),button('Deixar de seguir na conta','Deixar de seguir artista na conta',async()=>{await call({op:'subscribe',id:item.id,enabled:false});toast('Artista removido da conta.');}));}if(['album','playlist'].includes(kind)&&!isSpotify(item.id))text.append(button('Salvar na biblioteca da conta','Salvar na biblioteca do YouTube Music',async()=>{await call({op:'library-save',id:item.id,enabled:true});toast('Salvo na biblioteca do YouTube Music.');}));if(kind==='playlist'&&!isSpotify(item.id))text.append(button('Excluir playlist da conta','Excluir esta playlist no YouTube Music',async()=>{if(!confirm('Excluir esta playlist da sua conta YouTube Music?'))return;await call({op:'playlist-delete',id:item.id});toast('Playlist excluída.');await loadFeed('library');}));if(data.description)text.append(node('p','',data.description));hero.append(img,text);$('detail-header').replaceChildren(hero);$('detail-header').hidden=false;$('artist-more').hidden=!data.continuation&&!(kind==='artist'&&data.songsId);render();status(detail.songs.length+' músicas carregadas.');}
async function metadata(s){if(!s)throw Error('Escolha uma música primeiro.');if(s.albumId&&s.artistId)return s;if(isSpotify(s.id))return {...s,...await call({op:'spotify-track-info',id:s.id})};const result=await call({op:'search',query:s.title+' '+s.artists,kind:'songs'});return {...s,...result.songs.find(t=>t.id===s.id)};}
async function openAlbum(s){const data=await metadata(s);if(!data.albumId)throw Error('A fonte não informou o álbum desta faixa. Busque pelo nome na categoria Álbuns.');return openCollection({type:'album',id:data.albumId,title:data.albumName,thumbnail:data.thumbnail});}
async function openArtist(s){const data=await metadata(s);if(!data.artistId&&data.artists){const found=await call({op:'search',query:data.artists,kind:'artists'});const artists=(found.collections||[]).filter(x=>x.type==='artist');const match=artists.find(x=>x.title?.toLocaleLowerCase()===data.artists.toLocaleLowerCase())||artists[0];if(match)return openCollection(match);}if(!data.artistId)throw Error('Perfil de artista indisponível para esta faixa.');return openCollection({type:'artist',id:data.artistId,title:data.artists});}

function dockVisualizer(to=page){const box=document.querySelector('.visualizer-box');if(!box)return;if(innerWidth<1050&&to==='now')document.querySelector('.now-layout>div:first-child').append(box);else document.querySelector('.now-sidebar').insertBefore(box,$('side-now'));visualizer.update();}
window.addEventListener('resize',()=>dockVisualizer());

const headPicker=setupHeadPicker({getSettings:()=>settings,save:setSetting});
function applyAccent(color){if(!/^#[0-9a-f]{6}$/i.test(color))return;document.documentElement.style.setProperty('--accent',color);applyPalette(settings.primary,color);const logoColor=settings.logoMode==='custom'?settings.logoColor:color,logoKey=[settings.logoHead,settings.logoMode,logoColor].join('|');themeLogo.paint(logoColor,settings.logoHead,settings.logoMode==='original');if(appliedAccent!==logoKey){appliedAccent=logoKey;clearTimeout(accentIconTimer);accentIconTimer=setTimeout(()=>call({op:'accent',color:logoColor,head:settings.logoHead,original:settings.logoMode==='original'}).catch(()=>{}),120);}}

const windowChrome=setupWindowChrome(call);
let windowModeRevision=-1;
window.yuriWindowMode=state=>{windowChrome.update(state);const revision=Number(state.revision);if(Number.isFinite(revision)&&revision<windowModeRevision)return;if(Number.isFinite(revision))windowModeRevision=revision;document.body.classList.toggle('mini',!!state.mini);visualizer.update();};
call({op:'window-state'}).then(state=>window.yuriWindowMode(state)).catch(()=>{});


function renderHome(){const root=$('home');root.replaceChildren(node('small','label','DO SEU JEITO'),node('h1','',new Date().getHours()<12?'Bom dia.':new Date().getHours()<18?'Boa tarde.':'Boa noite.'));const shortcuts=node('div','home-shortcuts');for(const [to,label]of [['search','Buscar músicas'],['likes','Músicas curtidas'],['history','Ouvidas recentemente'],['downloads','Baixadas']])shortcuts.append(button(label,label,()=>navigate(to)));root.append(shortcuts);shortcuts.append(button('Suas playlists locais','Suas playlists locais',()=>{const playlists=entries('playlists');if(playlists.length)navigate('playlist',playlists[0][0]);else createPlaylist();}));if(feedKind==='library'){root.append(button('Nova playlist no YouTube Music','Criar playlist na conta',()=>askName('Nova playlist no YouTube Music','',async title=>{try{const created=await call({op:'playlist-create',title});await openCollection({type:'playlist',id:created.id});}catch(e){toast(e.message);}})));}const section=(title,tracks)=>{if(!tracks.length)return;root.append(node('h2','',title));const grid=node('div','home-cards');tracks.slice(0,12).forEach((s,index)=>{const card=node('article','home-card');card.classList.toggle('active',player.current?.id===s.id);card.dataset.trackId=s.id;const b=button('',(settings.homeAlbumClick?'Abrir álbum ou músicas do artista: ':'Reproduzir ')+s.title,()=>settings.homeAlbumClick?openTrackLocation(s):player.setQueue(tracks,index),'home-open');b.append(cover(s),node('strong','',s.title),node('small','',s.artists));const play=button('▶','Reproduzir '+s.title,()=>player.setQueue(tracks,index),'home-play');card.append(b,play);trackMenu.bind(card,s,{play:()=>player.setQueue(tracks,index)});grid.append(card);});root.append(grid);};section('Ouvidas recentemente',entries('history').map(([,r])=>r.song));section('Suas curtidas',entries('likes').map(([,r])=>r.song));const playlists=entries('playlists');if(playlists.length){root.append(node('h2','','Suas playlists'));const grid=node('div','home-shortcuts');for(const [id,p]of playlists.slice(0,12))grid.append(button(p.name,p.name,()=>navigate('playlist',id)));root.append(grid);}if(!entries('history').length&&!entries('likes').length&&!playlists.length){root.append(node('h2','','Seu próximo som começa aqui.'),node('p','','Busque seus artistas favoritos. Suas músicas e playlists vão aparecer aqui conforme você ouvir e salvar.'));}renderFeedShelves(root);}

function applyPalette(primary,accent){for(const [key,value]of Object.entries(palette(primary,accent)))document.documentElement.style.setProperty(key,value);}
function applyTheme(primary,accent){settings.primary=primary;settings.accent=accent;settings.autoAccent=false;library.settings.updated=now();applySettings();persist();}

function paintRange(input){const min=Number(input.min)||0,max=Number(input.max)||100,value=Number(input.value);input.style.setProperty('--range-fill',(max>min?Math.max(0,Math.min(100,100*(value-min)/(max-min))):0)+'%');}
document.addEventListener('input',event=>{if(event.target.matches('input[type=range]'))paintRange(event.target);});document.querySelectorAll('input[type=range]').forEach(paintRange);

const notificationsUI=setupNotifications({call,library:()=>library,persist,stamp:now,openAlbum:id=>openCollection({type:'album',id}),openArtist:id=>openCollection({type:'artist',id}),openUpdates:()=>updateUI.open(),toast});
const updateUI=setupUpdates({call,notify:version=>notificationsUI.update(version),save:()=>call({op:'state-save',data:JSON.stringify(library)}),toast,settings:()=>settings,persist:()=>{library.settings.updated=now();persist();}});

let trackLocationGeneration=0;
async function openTrackLocation(track){const ticket=++trackLocationGeneration,browse=browseGeneration;let data=track;if(!data.albumId){try{data=await metadata(track);}catch(error){if(ticket===trackLocationGeneration&&browse===browseGeneration)toast('Não foi possível localizar o álbum. Vamos tentar as músicas do artista.');}}
if(ticket!==trackLocationGeneration||browse!==browseGeneration)return;
if(data.albumId){const albumPage=browseGeneration+1;try{await openCollection({type:'album',id:data.albumId});return;}catch(error){if(ticket!==trackLocationGeneration||browseGeneration!==albumPage)return;toast('Este álbum não está disponível. Abrindo as músicas do artista.');}}
$('search-kind').value='songs';$('search-kind').dispatchEvent(new Event('change'));$('query').value=(data.artists||track.artists||data.title||track.title||'').trim();$('search').requestSubmit();}

for(const id of ['title','side-title','large-title']){const el=$(id);el.classList.add('music-title-link');el.setAttribute('role','link');el.tabIndex=0;el.setAttribute('aria-disabled',player.current?'false':'true');el.title='Abrir álbum ou músicas do artista';const activate=event=>{event.stopPropagation();event.preventDefault();if(player.current)openTrackLocation(player.current).catch(error=>toast(error.message));};el.addEventListener('click',activate);el.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' ')activate(event);});}

$('music-source').onchange=()=>{player.pause();setSetting('musicSource',$('music-source').value);songs=[];collections=[];detail=null;navigate('home');toast(settings.musicSource==='spotify'?'Spotify selecionado. Conecte sua conta nas configurações.':'Modo YouTube Music selecionado.');};
$('spotify-connect').onclick=guarded(async()=>{await call({op:'spotify-open'});$('spotify-connection-status').textContent='Entre na janela do Spotify. Depois feche essa janela para voltar ao Nocturne.';});
$('spotify-check').onclick=guarded(async()=>{const result=await call({op:'spotify-status'});$('spotify-connection-status').textContent=result.connected?'Spotify conectado. Você já pode buscar músicas.':result.message||'Conecte sua conta Spotify.';});
$('spotify-disconnect').onclick=guarded(async()=>{if(player.external)player.pause();await call({op:'spotify-logout'});$('spotify-connection-status').textContent='Spotify desconectado.';});
$('spotify-library').onclick=guarded(async()=>{const result=await call({op:'spotify-liked'});songs=(result.songs||[]).map(song);collections=[];navigate('search');$('heading').textContent='Curtidas do Spotify';status(songs.length+' músicas carregadas do Spotify.');});

let feedGeneration=0,feedData=null,feedKind='home';
async function loadFeed(kind){if(settings.musicSource!=='youtube')return;const ticket=++feedGeneration,browse=browseGeneration;status('Carregando…');const data=await call({op:kind});if(ticket!==feedGeneration||browse!==browseGeneration)return;feedData=data;feedKind=kind;navigate('home');renderHome();status('Tudo atualizado.');}
for(const [kind,label]of [['home','Início'],['explore','Explorar'],['library','Biblioteca da conta'],['recap','Retrospectiva']]){const b=button(label,label,()=>loadFeed(kind));b.className='feed-nav';document.querySelector('nav').append(b);}
$('yt-login').onclick=guarded(async()=>{const r=await nativeCall({op:'yt-login'});$('yt-status').textContent=r.message;});
$('yt-check').onclick=guarded(async()=>{$('yt-status').textContent='Verificando sua sessão…';const state=await meiro.auth(true);$('yt-status').textContent=state.message;});
$('yt-cancel').onclick=guarded(async()=>{await nativeCall({op:'yt-cancel'});$('yt-status').textContent='Login cancelado.';});
$('yt-import').onclick=guarded(async()=>{await nativeCall({op:'yt-import'});$('yt-status').textContent='Depois de salvar a sessão, use Verificar conexão para validar a conta.';});
$('yt-logout').onclick=guarded(async()=>{await nativeCall({op:'yt-logout'});await meiro.auth();$('yt-status').textContent='Sessão encerrada.';});
$('licenses-open').onclick=()=> $('licenses').showModal();

function renderFeedShelves(root){if(!feedData)return;const names={home:'Para sua noite',explore:'Explorar',library:'Sua biblioteca',recap:'Retrospectiva'};root.querySelector('h1').textContent=names[feedKind];const shelves=feedData.sections?.length?feedData.sections:[{title:feedData.title,songs:feedData.songs,collections:feedData.collections}];for(const shelf of shelves){const tracks=(shelf.songs||[]).map(song),items=shelf.collections||[];if(!tracks.length&&!items.length)continue;root.append(node('h2','feed-title',shelf.title||'Descubra mais'));const grid=node('div','meiro-shelf');for(const [index,t]of tracks.slice(0,20).entries()){const card=button('',t.title,()=>player.setQueue(tracks,index),'feed-card');card.append(cover(t),node('strong','',t.title),node('small','',t.artists));trackMenu.bind(card,t,{play:()=>player.setQueue(tracks,index)});grid.append(card);}for(const item of items.slice(0,20)){const card=button('',item.title,()=>openCollection(item),'feed-card '+item.type);card.append(cover(item),node('strong','',item.title),node('small','',item.artists||({album:'Álbum',artist:'Artista',playlist:'Playlist',podcast:'Podcast'})[item.type]||''));grid.append(card);}root.append(grid);if(shelf.continuation)root.append(button('Ver mais','Ver mais de '+shelf.title,async()=>{const more=await call({op:'browse-more',continuation:shelf.continuation});shelf.songs=[...(shelf.songs||[]),...(more.songs||[])];shelf.collections=[...(shelf.collections||[]),...(more.collections||[])];shelf.continuation=more.continuation;renderHome();}));}}
const queuePanel=node('div','now-queue'),relatedPanel=node('div','now-queue');queuePanel.hidden=true;relatedPanel.hidden=true;const lyricsPanel=$('lyrics'),nowRight=lyricsPanel.parentElement,tabs=node('div','now-tabs');let nowTab='lyrics';
function renderNowQueue(){queuePanel.replaceChildren();const clear=button('Limpar próximas','Limpar próximas músicas',()=>{const current=player.current;player.queue=current?[current]:[];player.index=current?0:-1;session.save(true);renderNowQueue();render();});queuePanel.append(clear);for(const [index,t]of player.queue.entries()){const row=button('',t.title,()=>player.play(index));row.classList.toggle('active',index===player.index);row.append(cover(t),node('span','',t.title));trackMenu.bind(row,t,{queue:true,play:()=>player.play(index)});queuePanel.append(row);}}
for(const [id,label]of [['queue','Próximas'],['lyrics','Letras'],['related','Relacionadas']])tabs.append(button(label,label,async()=>{nowTab=id;queuePanel.hidden=id!=='queue';lyricsPanel.hidden=id!=='lyrics';relatedPanel.hidden=id!=='related';for(const b of tabs.children)b.classList.toggle('active',b.textContent===label);if(id==='queue')renderNowQueue();if(id==='lyrics')await lyrics();if(id==='related'&&player.current){relatedPanel.replaceChildren(node('p','','Carregando…'));const result=await call({op:'related',id:player.current.id});relatedPanel.replaceChildren();const tracks=(result.songs||[]).map(song);for(const [index,t]of tracks.entries()){const b=button('',t.title,()=>player.setQueue(tracks,index));b.append(cover(t),node('span','',t.title));relatedPanel.append(b);}if(!tracks.length)relatedPanel.append(node('p','','Nenhuma recomendação disponível.'));}}));nowRight.prepend(tabs);nowRight.append(queuePanel,relatedPanel);setInterval(()=>{if(page==='now'&&nowTab==='queue')renderNowQueue();},3000);
const nav=document.querySelector('nav'),feedButtons=[...nav.querySelectorAll('.feed-nav')];feedButtons[0]?.remove();for(const b of feedButtons.slice(1)){b.dataset.feed=b.textContent.includes('Explorar')?'explore':b.textContent.includes('Biblioteca')?'library':'recap';}const ordered=[nav.querySelector('[data-page=home]'),nav.querySelector('[data-page=search]'),...feedButtons.slice(1),nav.querySelector('[data-page=queue]')];for(const b of ordered.filter(Boolean))nav.append(b);for(const b of [...nav.children].filter(b=>!ordered.includes(b)))nav.append(b);

async function loadAccountPlaylists(track){if(isSpotify(track.id)||settings.musicSource!=='youtube')return;const state=await meiro.auth();if(!state.connected)return;const data=await call({op:'library'});if(adding!==track||!$('add-dialog').open)return;const all=[...(data.collections||[]),...(data.sections||[]).flatMap(s=>s.collections||[])],seen=new Set();for(const item of all){if(item.type!=='playlist'||seen.has(item.id))continue;seen.add(item.id);$('add-options').append(button('YouTube Music · '+item.title,'Adicionar à playlist da conta '+item.title,async()=>{await call({op:'playlist-add',id:item.id,videoId:track.id});$('add-dialog').close();toast('Adicionada à playlist do YouTube Music.');}));}}

function rememberSearch(query){try{const old=JSON.parse(localStorage.getItem('nocturne-search-history')||'[]');localStorage.setItem('nocturne-search-history',JSON.stringify([query,...old.filter(v=>v!==query)].slice(0,20)));}catch{}}
function renderSearchFilters(data,query){$('search-filters')?.remove();const row=node('div','search-filters');row.id='search-filters';for(const filter of data.filters||[]){row.append(button(filter.label||'Tudo',filter.label||'Tudo',async()=>{const ticket=browseGeneration;const result=await call({op:'search',query,params:filter.params});if(ticket!==browseGeneration)return;songs=(result.songs||[]).map(song);collections=result.collections||[];render();renderSearchFilters(result,query);}));}if(data.continuation)row.append(button('Mais resultados','Mais resultados',async()=>{const ticket=browseGeneration;const more=await call({op:'search-more',continuation:data.continuation});if(ticket!==browseGeneration)return;songs.push(...(more.songs||[]).map(song));collections.push(...(more.collections||[]));render();renderSearchFilters(more,query);}));$('status').after(row);}
$('query').setAttribute('list','recent-searches');const recent=node('datalist');recent.id='recent-searches';document.body.append(recent);$('query').addEventListener('focus',()=>{recent.replaceChildren();try{for(const q of JSON.parse(localStorage.getItem('nocturne-search-history')||'[]')){const option=node('option');option.value=q;recent.append(option);}}catch{}});
$('license-read').onclick=guarded(async()=>{const text=await (await fetch('LICENSE.txt')).text();const pre=node('pre','license-text',text);$('license-content').replaceChildren(pre);});

for(const b of document.querySelectorAll('[data-feed]')){const kind=b.dataset.feed;b.textContent=({explore:'Explorar',library:'Biblioteca',recap:'Recap'})[kind];const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('class','nav-icon');svg.setAttribute('aria-hidden','true');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',({explore:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Zm4 6-2 6-6 2 2-6 6-2Z',library:'M4 4h6v16H4V4Zm10 0 6 1v15l-6-1V4Z',recap:'m3 16 5-5 4 3 8-9v5h-2V9l-6 7-4-3-4 4-1-1Z'})[kind]);svg.append(path);b.prepend(svg);}

async function enqueueTrack(track){if(player.external){await player.enqueue(track);session.save(true);render();toast('Adicionada à fila Spotify.');return;}let at=Math.max(0,player.index+1);while(player.queue[at]?.manualQueue)at++;player.queue.splice(at,0,{...song(track),key:crypto.randomUUID(),manualQueue:true});if(player.index<0){player.index=0;player.resumePosition=0;playbackChanged('track');}player.invalidatePrefetch();session.save(true);render();toast('Adicionada à fila.');}

setupSearchKind(document.getElementById('search-kind'));
